+// L3-022 Multi-view App - app.js
+(function() {
+  'use strict';
+
+  const STORAGE_KEY = 'l3-022-state';
+  let state = {
+    activeTab: 'dashboard',
+    logs: [],
+    deskTools: []
+  };
+
+  function init() {
+    loadState();
+    render();
+    setupEventListeners();
+  }
+
+  function loadState() {
+    try {
+      const saved = localStorage.getItem(STORAGE_KEY);
+      if (saved) {
+        state = JSON.parse(saved);
+      }
+    } catch (e) {
+      console.warn('Failed to load state:', e);
+    }
+  }
+
+  function saveState() {
+    try {
+      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
+    } catch (e) {
+      console.warn('Failed to save state:', e);
+    }
+  }
+
+  function setupEventListeners() {
+    document.querySelectorAll('[data-tab]').forEach(el => {
+      el.addEventListener('click', () => {
+        const tab = el.getAttribute('data-tab');
+        setActiveTab(tab);
+      });
+    });
+
+    document.getElementById('log-input')?.addEventListener('keydown', (e) => {
+      if (e.key === 'Enter' && e.target.value.trim()) {
+        addLog(e.target.value.trim());
+        e.target.value = '';
+      }
+    });
+
+    document.getElementById('tool-input')?.addEventListener('input', (e) => {
+      const val = e.target.value;
+      if (val.length > 0 && !state.deskTools.find(t => t.name === val)) {
+        state.deskTools.push({ name: val, active: false });
+        saveState();
+        renderTools();
+      }
+    });
+
+    document.querySelectorAll('[data-tool]').forEach(el => {
+      el.addEventListener('click', () => {
+        const toolName = el.getAttribute('data-tool');
+        toggleTool(toolName);
+      });
+    });
+  }
+
+  function setActiveTab(tab) {
+    state.activeTab = tab;
+    saveState();
+    render();
+  }
+
+  function addLog(message) {
+    const timestamp = new Date().toISOString();
+    state.logs.unshift({ message, timestamp });
+    if (state.logs.length > 100) state.logs.pop();
+    saveState();
+    renderLogs();
+  }
+
+  function toggleTool(name) {
+    const tool = state.deskTools.find(t => t.name === name);
+    if (tool) {
+      tool.active = !tool.active;
+      saveState();
+      renderTools();
+    }
+  }
+
+  function render() {
+    renderHeader();
+    renderDashboard();
+    renderLogs();
+    renderTools();
+  }
+
+  function renderHeader() {
+    const header = document.getElementById('app-header');
+    if (!header) return;
+    header.innerHTML = `
+      <h1>Multi-View Training App</h1>
+      <nav aria-label="Main Navigation">
+        <button data-tab="dashboard" class="${state.activeTab === 'dashboard' ? 'active' : ''}">Dashboard</button>
+        <button data-tab="logs" class="${state.activeTab === 'logs' ? 'active' : ''}">Activity Log</button>
+        <button data-tab="tools" class="${state.activeTab === 'tools' ? 'active' : ''}">Desk Tools</button>
+      </nav>
+    `;
+  }
+
+  function renderDashboard() {
+    const container = document.getElementById('dashboard-view');
+    if (!container) return;
+    container.innerHTML = `
+      <section aria-labelledby="welcome-heading">
+        <h2 id="welcome-heading">Welcome</h2>
+        <p>This is a local multi-view application built with HTML, CSS, and vanilla JavaScript.</p>
+        <ul>
+          <li>No external dependencies</li>
+          <li>Data persists in localStorage</li>
+          <li>Accessible and responsive design</li>
+        </ul>
+      </section>
+    `;
+  }
+
+  function renderLogs() {
+    const container = document.getElementById('logs-view');
+    if (!container) return;
+    const input = document.getElementById('log-input');
+    const list = document.createElement('ul');
+    list.setAttribute('role', 'list');
+    list.setAttribute('aria-label', 'Activity Log');
+    state.logs.forEach(log => {
+      const li = document.createElement('li');
+      li.textContent = `[${log.timestamp}] ${log.message}`;
+      list.appendChild(li);
+    });
+    container.innerHTML = `
+      <h2>Activity Log</h2>
+      <form aria-label="Add log entry">
+        <label for="log-input" id="log-label">Enter a log message:</label>
+        <input type="text" id="log-input" name="log-input" placeholder="Type something and press Enter..." aria-labelledby="log-label">
+        <button type="submit">Add</button>
+      </form>
+      <ul id="logs-list"></ul>
+    `;
+    const form = container.querySelector('form');
+    if (form) {
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
+        const input = form.querySelector('#log-input');
+        if (input && input.value.trim()) {
+          addLog(input.value);
+        }
+      });
+    }
+    container.querySelector('#logs-list')?.appendChild(list);
+  }
+
+  function renderTools() {
+    const container = document.getElementById('tools-view');
+    if (!container) return;
+    const input = document.getElementById('tool-input');
+    const list = document.createElement('ul');
+    list.setAttribute('role', 'list');
+    list.setAttribute('aria-label', 'Desk Tools');
+    state.deskTools.forEach(tool => {
+      const li = document.createElement('li');
+      li.innerHTML = `
+        <label style="display:flex; align-items:center; gap:0.5rem;">
+          <input type="checkbox" data-tool="${tool.name}" ${tool.active ? 'checked' : ''}>
+          <span>${tool.name}</span>
+        </label>
+      `;
+      list.appendChild(li);
+    });
+    container.innerHTML = `
+      <h2>Desk Tools</h2>
+      <form aria-label="Add desk tool">
+        <label for="tool-input" id="tool-label">Enter a new tool name:</label>
+        <input type="text" id="tool-input" name="tool-input" placeholder="e.g., Calculator, Notes..." aria-labelledby="tool-label">
+      </form>
+      <ul id="tools-list"></ul>
+    `;
+    const form = container.querySelector('form');
+    if (form) {
+      form.addEventListener('input', (e) => {
+        const val = e.target.value;
+        if (val.length > 0 && !state.deskTools.find(t => t.name === val)) {
+          state.deskTools.push({ name: val, active: false });
+          saveState();
+          renderTools();
+        }
+      });
+    }
+    container.querySelector('#tools-list')?.appendChild(list);
+  }
+
+  // Initialize app when DOM is ready
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', init);
+  } else {
+    init();
+  }
+})();

